/**
 * blog.js — client-side Markdown blog engine
 *
 * Routes:
 *   /blog.html                 → index (writings + recommended reads)
 *   /blog.html?post=<slug>     → renders /posts/<slug>/index.md
 *
 * Data:
 *   /posts/index.json          → generated by tools/build_blog.py
 *   /posts/reads.json          → hand-maintained recommended reads
 *
 * Everything heavy (Markdown parser, syntax highlighting, math) is fetched
 * lazily and only when a page actually needs it.
 */
(function () {
  'use strict';

  var $ = function (id) { return document.getElementById(id); };
  var VENDOR = '/assets/vendor/';

  /* ═══════════════════════════════ asset loading ═══════════════════════ */
  var loaded = {};
  function loadScript(src) {
    if (loaded[src]) return loaded[src];
    loaded[src] = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = src;
      s.onload = resolve;
      s.onerror = function () { reject(new Error('Failed to load ' + src)); };
      document.head.appendChild(s);
    });
    return loaded[src];
  }
  function loadCSS(href) {
    if (loaded[href]) return loaded[href];
    loaded[href] = new Promise(function (resolve) {
      var l = document.createElement('link');
      l.rel = 'stylesheet';
      l.href = href;
      l.onload = resolve;
      l.onerror = resolve;
      document.head.appendChild(l);
    });
    return loaded[href];
  }

  /* ═══════════════════════════════ small helpers ═══════════════════════ */
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function formatDate(str) {
    if (!str) return '';
    var d = new Date(str + 'T00:00:00');
    if (isNaN(d)) return str;
    return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  }

  function domainOf(url) {
    try { return new URL(url).hostname.replace(/^www\./, ''); }
    catch (_) { return 'the web'; }
  }

  function slugify(text) {
    return String(text).toLowerCase().trim()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-');
  }

  function setMeta(title, description) {
    document.title = title;
    $('page-title').textContent = title;
    var set = function (id, val) { var el = $(id); if (el && val) el.setAttribute('content', val); };
    set('page-description', description);
    set('og-title', title);
    set('og-description', description);
  }

  var ICON = {
    cal:   '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>',
    clock: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
    pen:   '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>',
    arrow: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M12 5l7 7-7 7"/></svg>',
    out:   '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><path d="M15 3h6v6M10 14 21 3"/></svg>'
  };

  /* ═══════════════════════════════ view state ══════════════════════════ */
  function show(which) {
    ['loading', 'error', 'content'].forEach(function (id) {
      var el = $(id);
      if (!el) return;
      if (id === 'loading') el.style.display = which === 'loading' ? 'flex' : 'none';
      else el.hidden = which !== id;
    });
  }

  function fail(message, code) {
    show('error');
    $('error-code').textContent = code || '404';
    $('error-message').textContent = message;
  }

  /* ═══════════════════════════════ front matter ════════════════════════ */
  function parseFrontMatter(raw) {
    var m = raw.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
    if (!m) return { meta: {}, body: raw };
    var meta = {};
    m[1].split('\n').forEach(function (line) {
      var i = line.indexOf(':');
      if (i < 0) return;
      var k = line.slice(0, i).trim();
      var v = line.slice(i + 1).trim().replace(/^["']|["']$/g, '');
      if (k) meta[k] = v;
    });
    return { meta: meta, body: raw.slice(m[0].length) };
  }

  /* ═══════════════════════════════ markdown prep ═══════════════════════ */
  function isAbsolute(url) { return /^(https?:|data:|mailto:|#|\/)/i.test(url); }

  function rewriteAssetPaths(md, base) {
    return md.replace(/(!?\[[^\]]*\])\(([^)]+)\)/g, function (full, label, urlPart) {
      var trimmed = urlPart.trim();
      var spaceIdx = trimmed.search(/\s+["']/);
      var url = spaceIdx >= 0 ? trimmed.slice(0, spaceIdx) : trimmed;
      var rest = spaceIdx >= 0 ? trimmed.slice(spaceIdx) : '';
      if (isAbsolute(url)) return full;
      return label + '(' + base + url + rest + ')';
    });
  }

  // Hide math from the Markdown parser, then put it back in the HTML.
  function protectMath(md) {
    var stash = [];
    var out = md.replace(/\$\$([\s\S]*?)\$\$/g, function (_, inner) {
      return 'MATHSTASHD' + (stash.push('$$' + inner + '$$') - 1) + 'ENDSTASH';
    });
    out = out.replace(/(?<!\$)\$(?!\s)([^$\n]+?)(?<!\s)\$(?!\$)/g, function (_, inner) {
      return 'MATHSTASHI' + (stash.push('$' + inner + '$') - 1) + 'ENDSTASH';
    });
    return { md: out, stash: stash };
  }

  function restoreMath(html, stash) {
    return html.replace(/MATHSTASH[DI](\d+)ENDSTASH/g, function (_, i) { return stash[+i]; });
  }

  function hasMath(md) { return /\$\$[\s\S]*?\$\$|\$[^$\n]+\$|\\\(|\\\[/.test(md); }

  function readingTime(md) {
    var words = md.replace(/```[\s\S]*?```/g, ' ').split(/\s+/).filter(Boolean).length;
    return Math.max(1, Math.round(words / 220)) + ' min read';
  }

  /* ═══════════════════════════════ HTML post-processing ════════════════ */
  function enhance(root) {
    // code blocks → framed with a language label and a copy button
    root.querySelectorAll('pre > code').forEach(function (code) {
      var pre = code.parentNode;
      if (pre.parentNode.classList.contains('code-block')) return;
      var lang = (code.className.match(/language-([\w+#-]+)/) || [])[1] || '';
      var wrap = document.createElement('div');
      wrap.className = 'code-block';
      pre.parentNode.insertBefore(wrap, pre);

      var bar = document.createElement('div');
      bar.className = 'code-block__bar';
      bar.innerHTML = '<span class="code-block__lang">' + esc(lang || 'code') + '</span>' +
        '<button class="code-block__copy" type="button">Copy</button>';
      wrap.appendChild(bar);
      wrap.appendChild(pre);

      bar.querySelector('button').addEventListener('click', function (e) {
        var btn = e.currentTarget;
        navigator.clipboard.writeText(code.textContent).then(function () {
          btn.textContent = 'Copied';
          setTimeout(function () { btn.textContent = 'Copy'; }, 1400);
        }).catch(function () { btn.textContent = 'Press ⌘C'; });
      });
    });

    // images → figures with captions drawn from alt text
    root.querySelectorAll('img').forEach(function (img) {
      img.setAttribute('loading', 'lazy');
      img.setAttribute('decoding', 'async');
      if (img.closest('figure')) return;
      var fig = document.createElement('figure');
      img.parentNode.insertBefore(fig, img);
      fig.appendChild(img);
      var alt = img.getAttribute('alt');
      if (alt) {
        var cap = document.createElement('figcaption');
        cap.textContent = alt;
        fig.appendChild(cap);
      }
      // a lone image inside a paragraph leaves an empty <p> behind
      var p = fig.parentNode;
      if (p && p.tagName === 'P' && !p.textContent.trim()) {
        p.parentNode.insertBefore(fig, p);
        p.remove();
      }
    });

    // tables can be wider than the measure — let them scroll on their own
    root.querySelectorAll('table').forEach(function (table) {
      if (table.parentNode.classList.contains('table-scroll')) return;
      var box = document.createElement('div');
      box.className = 'table-scroll';
      table.parentNode.insertBefore(box, table);
      box.appendChild(table);
    });

    // external links open in a new tab
    root.querySelectorAll('a[href]').forEach(function (a) {
      if (/^https?:/i.test(a.getAttribute('href')) && a.hostname !== location.hostname) {
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
      }
    });

    // heading anchors
    var used = {};
    root.querySelectorAll('h2, h3').forEach(function (h) {
      var id = h.id || slugify(h.textContent);
      if (used[id]) id = id + '-' + (used[id] = used[id] + 1);
      else used[id] = 1;
      h.id = id;
      var a = document.createElement('a');
      a.className = 'anchor';
      a.href = '#' + id;
      a.setAttribute('aria-label', 'Link to this section');
      a.textContent = '#';
      h.insertBefore(a, h.firstChild);
    });
  }

  /* ═══════════════════════════════ table of contents ═══════════════════ */
  function buildToc(root) {
    var heads = Array.prototype.slice.call(root.querySelectorAll('h2, h3'));
    var h2count = heads.filter(function (h) { return h.tagName === 'H2'; }).length;
    if (h2count < 3) return;

    var list = $('toc-list');
    list.innerHTML = heads.map(function (h) {
      var text = h.textContent.replace(/^#/, '').trim();
      return '<li class="' + (h.tagName === 'H3' ? 'lv3' : 'lv2') + '">' +
        '<a href="#' + h.id + '">' + esc(text) + '</a></li>';
    }).join('');
    $('toc').hidden = false;
    document.querySelector('.reader').classList.add('has-rail');

    var links = {};
    list.querySelectorAll('a').forEach(function (a) { links[a.getAttribute('href').slice(1)] = a; });

    var visible = new Set();
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) visible.add(e.target.id); else visible.delete(e.target.id);
      });
      var current = heads.filter(function (h) { return visible.has(h.id); })[0];
      if (!current) {
        // nothing on screen — fall back to the last heading above the fold
        for (var i = heads.length - 1; i >= 0; i--) {
          if (heads[i].getBoundingClientRect().top < 120) { current = heads[i]; break; }
        }
      }
      Object.keys(links).forEach(function (id) {
        links[id].toggleAttribute('aria-current', !!current && current.id === id);
      });
    }, { rootMargin: '-80px 0px -70% 0px', threshold: 0 });

    heads.forEach(function (h) { io.observe(h); });
  }

  /* ═══════════════════════════════ reading chrome ══════════════════════ */
  function readingChrome(enableAutoHide) {
    var bar = $('reader-bar');
    var progress = $('progress');
    var last = window.scrollY;
    var ticking = false;

    function update() {
      var y = window.scrollY;
      var max = document.documentElement.scrollHeight - window.innerHeight;
      bar.setAttribute('data-scrolled', y > 4 ? 'true' : 'false');
      if (progress) progress.style.width = (max > 0 ? Math.min(100, (y / max) * 100) : 0) + '%';
      if (enableAutoHide) {
        var goingDown = y > last && y > 180;
        bar.setAttribute('data-hidden', goingDown ? 'true' : 'false');
      }
      last = y;
      ticking = false;
    }

    update();
    window.addEventListener('scroll', function () {
      if (!ticking) { ticking = true; requestAnimationFrame(update); }
    }, { passive: true });

    // never keep the bar hidden while a keyboard user is tabbing through it
    bar.addEventListener('focusin', function () { bar.setAttribute('data-hidden', 'false'); });
  }

  /* ═══════════════════════════════ data ════════════════════════════════ */
  function getJSON(url) {
    return fetch(url).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  var dataPromise = null;
  function loadData() {
    if (!dataPromise) {
      dataPromise = Promise.all([
        getJSON('/posts/index.json').catch(function () { return { posts: [] }; }),
        getJSON('/posts/reads.json').catch(function () { return { reads: [] }; })
      ]).then(function (r) {
        return { posts: (r[0] && r[0].posts) || [], reads: (r[1] && r[1].reads) || [] };
      });
    }
    return dataPromise;
  }

  /* ═══════════════════════════════ post view ═══════════════════════════ */
  function renderPost(slug) {
    show('loading');
    readingChrome(true);
    $('back-label').textContent = 'All writing';
    $('back-link').href = '/blog.html';

    var basePath = '/posts/' + slug + '/';

    fetch(basePath + 'index.md').then(function (res) {
      if (!res.ok) throw Object.assign(new Error('HTTP ' + res.status), { status: res.status });
      return res.text();
    }).then(function (raw) {
      var parsed = parseFrontMatter(raw);
      var meta = parsed.meta;
      var body = parsed.body;

      var title = meta.title || slug.replace(/-/g, ' ');
      setMeta(title + ' | Sagalpreet Singh', meta.description || '');
      $('crumb').textContent = title;

      var tags = (meta.tags || '').split(',').map(function (t) { return t.trim(); }).filter(Boolean);
      $('post-head').innerHTML =
        '<h1>' + esc(title) + '</h1>' +
        '<div class="meta-row">' +
          (meta.date ? '<span>' + ICON.cal + formatDate(meta.date) + '</span>' : '') +
          '<span>' + ICON.clock + esc(meta.readtime || readingTime(body)) + '</span>' +
        '</div>' +
        (tags.length ? '<div class="tags">' + tags.map(function (t) {
          return '<a class="tag" href="/blog.html?tag=' + encodeURIComponent(t) + '">' + esc(t) + '</a>';
        }).join('') + '</div>' : '');

      var math = protectMath(body);
      var md = rewriteAssetPaths(math.md, basePath);

      return loadScript(VENDOR + 'showdown.min.js').then(function () {
        var converter = new showdown.Converter({
          tables: true,
          strikethrough: true,
          tasklists: true,
          ghCodeBlocks: true,
          literalMidWordUnderscores: true,
          simpleLineBreaks: false,
          smoothLivePreview: true,
          simplifiedAutoLink: true,
          disableForced4SpacesIndentedSublists: true,
          omitExtraWLInCodeBlocks: true,
          ghCompatibleHeaderId: true,
          parseImgDimensions: true
        });
        var html = restoreMath(converter.makeHtml(md), math.stash);
        var target = $('post-body');
        target.innerHTML = html;
        enhance(target);
        buildToc(target);
        show('content');

        var jobs = [];

        if (target.querySelector('pre code')) {
          jobs.push(loadScript(VENDOR + 'highlight.min.js').then(function () {
            target.querySelectorAll('pre code').forEach(function (b) {
              try { window.hljs.highlightElement(b); } catch (_) {}
            });
          }));
        }

        if (hasMath(body)) {
          jobs.push(
            loadCSS(VENDOR + 'katex/katex.min.css')
              .then(function () { return loadScript(VENDOR + 'katex/katex.min.js'); })
              .then(function () { return loadScript(VENDOR + 'katex/auto-render.min.js'); })
              .then(function () {
                window.renderMathInElement(target, {
                  delimiters: [
                    { left: '$$', right: '$$', display: true },
                    { left: '$', right: '$', display: false },
                    { left: '\\[', right: '\\]', display: true },
                    { left: '\\(', right: '\\)', display: false }
                  ],
                  throwOnError: false
                });
              })
          );
        }

        jobs.push(loadData().then(function (data) { renderPager(data.posts, slug); }));
        return Promise.all(jobs);
      });
    }).catch(function (err) {
      if (err && err.status === 404) fail('That post doesn’t exist — check the URL.', '404');
      else fail('Could not load this post: ' + err.message, '!');
      console.error('[blog]', err);
    });
  }

  function renderPager(posts, slug) {
    var i = posts.findIndex(function (p) { return p.slug === slug; });
    if (i < 0) return;
    var newer = posts[i - 1];
    var older = posts[i + 1];
    if (!newer && !older) return;
    $('post-foot').innerHTML = '<div class="pager">' +
      (older ? '<a class="pager__item" href="/blog.html?post=' + encodeURIComponent(older.slug) + '">' +
        '<span class="pager__dir">Older</span><span class="pager__title">' + esc(older.title) + '</span></a>' : '') +
      (newer ? '<a class="pager__item pager__item--next" href="/blog.html?post=' + encodeURIComponent(newer.slug) + '">' +
        '<span class="pager__dir">Newer</span><span class="pager__title">' + esc(newer.title) + '</span></a>' : '') +
      '</div>';
    $('post-foot').hidden = false;
  }

  /* ═══════════════════════════════ index view ══════════════════════════ */
  var active = [];

  function matches(item) {
    if (!active.length) return true;
    return (item.tags || []).some(function (t) { return active.indexOf(t) !== -1; });
  }

  function tagsHtml(tags) {
    return (tags || []).map(function (t) {
      return '<span class="tag">' + esc(t) + '</span>';
    }).join('');
  }

  function renderIndex(data) {
    setMeta('Blog | Sagalpreet Singh', 'Research notes, essays and write-ups by Sagalpreet Singh.');
    $('crumb').textContent = 'Blog';
    $('back-label').textContent = 'Home';
    $('back-link').href = '/';

    var all = {};
    data.posts.concat(data.reads).forEach(function (x) {
      (x.tags || []).forEach(function (t) { all[t] = (all[t] || 0) + 1; });
    });
    var allTags = Object.keys(all).sort();

    var posts = data.posts.filter(matches);
    var reads = data.reads.filter(matches);

    var html =
      '<header class="index-head">' +
        '<h1>Writing</h1>' +
        '<p>Research notes, essays and the occasional write-up of something I built. ' +
        'Also a shelf of pieces by other people that I keep coming back to.</p>' +
      '</header>';

    if (allTags.length) {
      html += '<div class="filter">' +
        '<div class="filter__head"><span>Filter by tag</span>' +
        '<button class="filter__clear" type="button" id="clear-tags"' + (active.length ? '' : ' hidden') + '>Clear</button></div>' +
        '<div class="filter__cloud">' +
          allTags.map(function (t) {
            return '<button class="chip" type="button" data-tag="' + esc(t) + '" aria-pressed="' +
              (active.indexOf(t) !== -1) + '">' + esc(t) + '</button>';
          }).join('') +
        '</div></div>';
    }

    html += '<h2 class="list-title">Posts</h2>';
    if (!posts.length) {
      html += '<p class="empty-state">Nothing here with those tags.</p>';
    } else {
      html += posts.map(function (p) {
        var href = '/blog.html?post=' + encodeURIComponent(p.slug);
        return '<article class="post-card">' +
          '<h3><a href="' + href + '">' + esc(p.title) + '</a></h3>' +
          '<div class="meta-row">' +
            (p.date ? '<span>' + ICON.cal + formatDate(p.date) + '</span>' : '') +
            (p.readtime ? '<span>' + ICON.clock + esc(p.readtime) + '</span>' : '') +
          '</div>' +
          (p.description ? '<p class="post-card__desc">' + esc(p.description) + '</p>' : '') +
          '<div class="row" style="justify-content:space-between;gap:var(--sp-4)">' +
            '<div class="tags">' + tagsHtml(p.tags) + '</div>' +
            '<a class="post-card__more" href="' + href + '">Read' + ICON.arrow + '</a>' +
          '</div>' +
        '</article>';
      }).join('');
    }

    if (data.reads.length) {
      html += '<h2 class="list-title">Recommended reads</h2>';
      if (!reads.length) {
        html += '<p class="empty-state">Nothing here with those tags.</p>';
      } else {
        html += reads.map(function (r) {
          return '<article class="post-card">' +
            '<h3><a href="' + esc(r.url) + '" target="_blank" rel="noopener noreferrer">' + esc(r.title) + '</a></h3>' +
            '<div class="meta-row">' +
              (r.author ? '<span>' + ICON.pen + esc(r.author) + '</span>' : '') +
              (r.date ? '<span>' + ICON.cal + formatDate(r.date) + '</span>' : '') +
              (r.readtime ? '<span>' + ICON.clock + esc(r.readtime) + '</span>' : '') +
            '</div>' +
            (r.description ? '<p class="post-card__desc">' + esc(r.description) + '</p>' : '') +
            '<div class="row" style="justify-content:space-between;gap:var(--sp-4)">' +
              '<div class="tags">' + tagsHtml(r.tags) + '</div>' +
              '<a class="post-card__more" href="' + esc(r.url) + '" target="_blank" rel="noopener noreferrer">' +
                domainOf(r.url) + ICON.out + '</a>' +
            '</div>' +
          '</article>';
        }).join('');
      }
    }

    $('post-head').innerHTML = '';
    $('post-body').innerHTML = html;
    $('post-body').classList.remove('prose');
    $('post-foot').hidden = true;
    show('content');

    $('post-body').querySelectorAll('.chip[data-tag]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var t = btn.getAttribute('data-tag');
        var i = active.indexOf(t);
        if (i === -1) active.push(t); else active.splice(i, 1);
        syncUrl();
        renderIndex(data);
      });
    });
    var clear = $('clear-tags');
    if (clear) clear.addEventListener('click', function () {
      active = [];
      syncUrl();
      renderIndex(data);
    });
  }

  function syncUrl() {
    var url = new URL(location.href);
    if (active.length) url.searchParams.set('tag', active.join(','));
    else url.searchParams.delete('tag');
    history.replaceState(null, '', url);
  }

  /* ═══════════════════════════════ router ══════════════════════════════ */
  var params = new URLSearchParams(location.search);
  var slug = params.get('post');

  if (slug && /^[\w.-]+$/.test(slug)) {
    renderPost(slug);
  } else {
    var tagParam = params.get('tag');
    if (tagParam) active = tagParam.split(',').map(function (t) { return t.trim(); }).filter(Boolean);
    readingChrome(false);
    show('loading');
    loadData().then(renderIndex).catch(function (err) {
      fail('Could not load the post list: ' + err.message, '!');
    });
  }
})();
